    float targetY;
    float targetX;
    float f;
    float targetY2;
    float targetY3;
    float f2 = 0.5f;
    float targetX2 = mapW * 32 * 0.5f;
    float targetY4 = mapH * 32 * 0.5f;
    int playerHouse = MainActivity.this.renderWords[5] & 255;
    boolean found = false;
    int i3 = 0;
    while (true) {
        i = Integer.MIN_VALUE;
        if (i3 >= 128 || found) {
            break;
        }
        int base = (i3 * 12) + MainActivity.STRUCT_OFFSET;
        int meta = MainActivity.this.renderWords[base];
        if ((Integer.MIN_VALUE & meta) == 0) {
            targetX = targetX2;
            f = f2;
            targetY2 = targetY4;
        } else if ((meta & 255) != playerHouse) {
            targetX = targetX2;
            f = f2;
            targetY2 = targetY4;
        } else {
            int count = (meta >>> 16) & 255;
            if (count <= 0) {
                targetX = targetX2;
                f = f2;
                targetY2 = targetY4;
            } else {
                float sx2 = 0.0f;
                float sy = 0.0f;
                int used = 0;
                f = f2;
                int y = 0;
                while (y < count && y < 9) {
