from PIL import Image
from collections import deque
im=Image.open('/tmp/opencode/current.png').convert('RGB')
# mask near gold
mask=set()
for y in range(0,1080,2):
 for x in range(0,2340,2):
  r,g,b=im.getpixel((x,y))
  if abs(r-223)<18 and abs(g-196)<18 and abs(b-131)<22: mask.add((x,y))
print('mask',len(mask))
seen=set(); comps=[]
for p in list(mask):
 if p in seen: continue
 q=deque([p]); seen.add(p); pts=[]
 while q:
  x,y=q.popleft(); pts.append((x,y))
  for dx,dy in ((2,0),(-2,0),(0,2),(0,-2)):
   n=(x+dx,y+dy)
   if n in mask and n not in seen: seen.add(n); q.append(n)
 if len(pts)>8:
  xs=[a for a,b in pts]; ys=[b for a,b in pts]
  comps.append((len(pts),(min(xs),min(ys),max(xs),max(ys))))
comps.sort(reverse=True)
for c in comps[:30]: print(c)
PY

