from pathlib import Path
rom=Path('/tmp/opencode/rom/Dune_Rus.gen').read_bytes()

def decode_planar(b):
    out=[]
    for y in range(8):
        for x in range(8):
            bit=7-x
            out.append((b[y]>>bit)&1|(((b[8+y]>>bit)&1)<<1)|(((b[16+y]>>bit)&1)<<2)|(((b[24+y]>>bit)&1)<<3))
    return out
def decode_packed(b):
    out=[]
    for y in range(8):
        for x in range(8):
            out.append((b[y*4+x//2]>>(4 if x%2==0 else 0))&15)
    return out
def decode_1bpp(b):
    out=[]
    for y in range(8):
        for x in range(8):
            out.append((b[y]>>(7-x))&1)
    return out

def good(px):
    nz=sum(1 for v in px if v)
    if not (6<=nz<=26): return False
    cols=[sum(1 for y in range(8) if px[y*8+x]) for x in range(8)]
    active=[x for x,c in enumerate(cols) if c]
    if len(active)<4 or len(active)>7: return False
    if active[0]>2 or active[-1]<5: return False
    if max(cols)>6: return False
    if sum(1 for v in px[:8] if v)>2 or sum(1 for v in px[56:] if v)>2: return False
    return True

for name,step,dec in [('planar32',32,decode_planar),('packed32',32,decode_packed),('1bpp8',8,decode_1bpp)]:
    g=[]
    for off in range(0,len(rom)-step+1,step):
        if good(dec(rom[off:off+step])): g.append(off//step)
    runs=[]; start=g[0]; prev=start
    for i in g[1:]:
        if i==prev+1: prev=i
        else: runs.append((start,prev)); start=prev=i
    runs.append((start,prev))
    runs.sort(key=lambda r:r[1]-r[0],reverse=True)
    print(name,'good',len(g),'top runs',[(hex(a*step),hex(b*step),b-a+1) for a,b in runs[:10]])
