    d.text((0,0),c,font=f,fill=1)
    canon[c]=[sum(1 for y in range(8) if im.getpixel((x,y))) for x in range(8)]
    # store rows as ints
    canon[c+'_rows']=[sum(im.getpixel((x,y))<<(7-x) for x in range(8)) for y in range(8)]
