from pathlib import Path
from PIL import Image, ImageDraw, ImageFont
rom=Path('/tmp/opencode/rom/Dune_Rus.gen').read_bytes()
f=ImageFont.truetype('/tmp/opencode/fonts/PressStart2P.ttf',8)
chars='0123456789'
canon={}
for c in chars:
    im=Image.new('1',(8,8),0); d=ImageDraw.Draw(im); d.text((0,0),c,font=f,fill=1)
    canon[c]=[sum(im.getpixel((x,y))<<(7-x) for x in range(8)) for y in range(8)]

def rev(b): return int(f'{b:08b}'[::-1],2)
def variants(off):
    raw=list(rom[off:off+8])
    yield 'raw',raw
    yield 'rev',[rev(x) for x in raw]
    yield 'inv',[x^255 for x in raw]
    yield 'revinv',[rev(x)^255 for x in raw]
    # column-major: pack columns as bytes
    col=[]
    for x in range(8):
        v=0
        for y in range(8): v |= ((raw[y]>>(7-x))&1)<<(7-y)
        col.append(v)
    yield 'col',col
def dist(a,b): return sum((x^y).bit_count() for x,y in zip(a,b))
res=[]
for off in range(0,len(rom)-8):
    best=(999,'')
    for name,rows in variants(off):
        d=min(dist(rows,canon[c]) for c in '0O')
        if d<best[0]: best=(d,name)
    if best[0]<=12: res.append((best[0],off,best[1]))
res.sort()
print('hits',len(res))
for d,off,name in res[:30]:
    score=0
    for i,c in enumerate(chars):
        rows=list(variants(off+i*8))[0][1]
        dd=min(dist(rows,canon[c]) for c in chars)
        if dd<=12: score+=1
    print(hex(off),d,name,'score',score)
